import subprocess, pymupdf

OUT = "/root/tiktok-design/cine"; IMG = f"{OUT}/img"

GRAIN = ("data:image/svg+xml;utf8,"
"<svg xmlns='http://www.w3.org/2000/svg' width='300' height='300'>"
"<filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/>"
"<feColorMatrix type='saturate' values='0'/></filter>"
"<rect width='100%' height='100%' filter='url(%23n)' opacity='0.55'/></svg>")

CSS = """
@page { size:1080px 1920px; margin:0; }
* { margin:0; padding:0; box-sizing:border-box; }
html { -webkit-print-color-adjust:exact; print-color-adjust:exact; }
body { background:#000; }
.slide { width:1080px; height:1920px; position:relative; overflow:hidden;
  page-break-after:always; font-family:'Inter',sans-serif; color:#F0EBE3; background:#0A0A0B; }
.photo { position:absolute; inset:0; background-size:cover; background-position:center; }
.grade { position:absolute; inset:0; background:linear-gradient(to bottom,
  rgba(6,8,10,0.80) 0%, rgba(6,8,10,0.36) 32%, rgba(6,8,10,0.50) 62%, rgba(6,8,10,0.96) 100%); }
.vignette { position:absolute; inset:0;
  background:radial-gradient(ellipse at 50% 46%, transparent 42%, rgba(0,0,0,0.76) 100%); }
.grain { position:absolute; inset:0; opacity:0.15; background-image:url("%GRAIN%");
  background-size:300px 300px; mix-blend-mode:screen; }
.bar { position:absolute; left:0; right:0; height:64px; background:#000; z-index:5; }
.bar.top { top:0; } .bar.bottom { bottom:0; }
.abs { position:absolute; left:88px; right:88px; }
.eyebrow { font-family:'JetBrains Mono',monospace; font-size:30px; letter-spacing:0.30em;
  text-transform:uppercase; color:#6FD3E4; }
.rule { width:120px; height:6px; background:#6FD3E4; }
h1 { font-family:'Anton',sans-serif; font-weight:400; font-size:168px; line-height:0.90;
  letter-spacing:-0.01em; text-transform:uppercase; color:#F0EBE3; text-shadow:0 6px 40px rgba(0,0,0,0.85); }
h1.sm { font-size:112px; }
h1.money { font-size:132px; color:#6FD3E4; }
.arrow { font-family:'Inter',sans-serif; font-weight:800; color:#6FD3E4; }
.sub { font-family:'Inter',sans-serif; font-weight:500; font-size:50px; line-height:1.30;
  color:#E6E1D8; text-shadow:0 4px 24px rgba(0,0,0,0.9); }
.sub strong { font-weight:800; color:#FFFFFF; }
.klabel { font-family:'JetBrains Mono',monospace; font-size:27px; letter-spacing:0.16em;
  text-transform:uppercase; color:#6FD3E4; margin-bottom:10px; }
.ktext { font-family:'Inter',sans-serif; font-weight:400; font-size:41px; line-height:1.34;
  color:#CFC9BF; margin-bottom:38px; }
.ktext strong { color:#FFFFFF; font-weight:800; }
.ktext .n { color:#6FD3E4; font-weight:800; }
.mv { display:flex; align-items:baseline; margin-bottom:30px; }
.mv .num { font-family:'Anton',sans-serif; font-size:64px; color:#6FD3E4; width:96px; flex:none; line-height:1; }
.mv .txt { font-family:'Inter',sans-serif; font-weight:400; font-size:42px; line-height:1.28; color:#E2DCD3; }
.mv .txt strong { color:#FFFFFF; font-weight:800; }
.grid { display:flex; flex-wrap:wrap; }
.cell { width:50%; margin-bottom:34px; }
.cell .v { font-family:'Anton',sans-serif; font-size:88px; color:#6FD3E4; line-height:1; margin-bottom:8px; }
.cell .l { font-family:'Inter',sans-serif; font-weight:600; font-size:32px; color:#C4BEB4; line-height:1.25; }
.src { font-family:'JetBrains Mono',monospace; font-size:25px; line-height:1.5; color:#8E8981; }
.slate { font-family:'JetBrains Mono',monospace; font-size:24px; letter-spacing:0.16em;
  text-transform:uppercase; color:#6E6A63; }
"""

def layer(u): return (f'<div class="photo" style="background-image:url({u})"></div>'
    f'<div class="grade"></div><div class="vignette"></div><div class="grain"></div>')
def bars(sc,tag): return (f'<div class="bar top"><div class="slate" style="position:absolute;left:88px;top:17px;">Human Architect &nbsp;&middot;&nbsp; {sc}</div></div>'
