def slide(p): return f'<section class="slide">{"".join(p)}</section>'
def blk(t,h): return f'<div class="abs" style="top:{t}px;">{h}</div>'
def mv(n,t): return f'<div class="mv"><div class="num">{n}</div><div class="txt">{t}</div></div>'
def cell(v,l): return f'<div class="cell"><div class="v">{v}</div><div class="l">{l}</div></div>'

STREET=f"file://{IMG}/walk-street.jpg"; FOREST=f"file://{IMG}/walk-forest.jpg"; SLEEP=f"file://{IMG}/sleep-room.jpg"

S=[]
# 1 COVER
S.append(slide([
 layer(STREET), bars("SC 01 / 06","The Plan"),
 blk(150,'<div class="eyebrow">The Manager&rsquo;s Plan</div>'),
 blk(224,'<div class="rule"></div>'),
 blk(380,'<h1 class="money">2,145 <span class="arrow">&rarr;</span> 10,000</h1>'),
 blk(600,'<h1 class="sm">followers<br>in 90 days.</h1>'),
 blk(1000,'<div class="sub">One niche. One format.<br><strong>Posted every single day.</strong></div>'),
]))
# 2 WHERE YOU ARE
S.append(slide([
 layer(SLEEP), bars("SC 02 / 06","Now"),
 blk(150,'<div class="eyebrow">Where you are now</div>'),
 blk(224,'<div class="rule"></div>'),
 blk(360,'<div class="grid">'+cell("2,145","followers")+cell("16.4K","likes")+
   cell("72","posts")+cell("358,627","lifetime views")+'</div>'),
 blk(760,'''<div class="klabel">Last 30 days</div>
<div class="ktext"><strong>29 posts</strong> &nbsp;&middot;&nbsp; <strong>10,176 views</strong> &nbsp;&middot;&nbsp; <span class="n">350 each</span></div>
<div class="klabel">The concentration</div>
<div class="ktext">Two videos carry <span class="n">90%</span> of everything you have ever posted. The rest is noise.</div>
<div class="klabel">The conversion</div>
<div class="ktext">0.6% of your viewers follow you. Fix that and every number moves.</div>'''),
]))
# 3 WHAT CHANGED
S.append(slide([
 layer(FOREST), bars("SC 03 / 06","2026 Rules"),
 blk(150,'<div class="eyebrow">What changed in 2026</div>'),
 blk(224,'<div class="rule"></div>'),
 blk(340,
  mv("01","<strong>Watch time and completion</strong> are 40&ndash;50% of the ranking. Nothing else is close.")
 +mv("02","The hook lands in the <strong>first 1&ndash;2 seconds</strong>. Under 12 spoken words.")
 +mv("03","<strong>Niche beats reach.</strong> The feed now rewards community fit over random virals.")
 +mv("04","<strong>70% completion</strong> is the target. Below it, the video stops moving.")),
 blk(1560,'<div class="src">Sources: Hootsuite, Krumzi, SocialPilot, Nemovideo &mdash; 2026 algorithm roundups.</div>'),
]))
# 4 THE ARITHMETIC
S.append(slide([
 layer(STREET), bars("SC 04 / 06","The Math"),
 blk(150,'<div class="eyebrow">The arithmetic</div>'),
 blk(224,'<div class="rule"></div>'),
 blk(340,'''<div class="klabel">The gap</div>
<div class="ktext">2,145 to 10,000 = <span class="n">7,855</span> followers in 90 days = <span class="n">87 a day</span>.</div>
<div class="klabel">The views that buys</div>
<div class="ktext">At 1% of viewers following: <span class="n">8,700 views a day</span>. That is <span class="n">261,000</span> over 90 days.</div>
<div class="klabel">The posts that needs</div>
<div class="ktext">Three posts a day = <span class="n">967 views each</span>.<br>You average 350. <strong>You need 3x, not 30x.</strong></div>'''),
]))
# 5 THE SYSTEM
S.append(slide([
 layer(FOREST), bars("SC 05 / 06","The System"),
 blk(150,'<div class="eyebrow">Five moves, every day</div>'),
 blk(224,'<div class="rule"></div>'),
 blk(340,
  mv("01","<strong>One niche for 90 days.</strong> Energy and the body. Nothing else.")
 +mv("02","<strong>One format.</strong> Talking head, 15&ndash;25 seconds, face in frame.")
 +mv("03","<strong>Three posts a day, spaced.</strong> Never a burst &mdash; they cannibalise.")
 +mv("04","<strong>Hook in the first second.</strong> Open on the idea, never a greeting.")
 +mv("05","<strong>Caption every post.</strong> Keywords written and spoken, three hashtags.")),
]))
# 6 THE MONEY
S.append(slide([
 layer(SLEEP), bars("SC 06 / 06","The Money"),
 blk(150,'<div class="eyebrow">What it pays, by stage</div>'),
 blk(224,'<div class="rule"></div>'),
 blk(340,
  mv("A","<strong>2,145 followers today.</strong> Platform pays &pound;0. Nano brand deals &pound;30&ndash;&pound;150 a video.")
 +mv("B","<strong>10,000 followers.</strong> Creator Rewards unlocks, and you enter the micro tier: &pound;250&ndash;&pound;1,000 a video.")
 +mv("C","<strong>Own offer &mdash; the only line that scales.</strong> 10,000 views &times; 1% to link &times; 3% = 3 sales.")
 +mv("&pound;","<strong>&pound;50 offer = &pound;150/mo. &pound;200 = &pound;600/mo. &pound;2,000 = &pound;6,000/mo.</strong>")),
]))

html=f'''<!DOCTYPE html><html><head><meta charset="utf-8">
<style>{CSS.replace("%GRAIN%",GRAIN)}</style></head><body>{"".join(S)}</body></html>'''
